"""Measure a per-snapshot MILP: 12 int vars + blame booleans + admissibility formula."""
import json, sys, time
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
import z3
import infer, genbig
from instance import parse_request


def snapshot_base(inst, si, ctx):
    """(solver vars, constraints, per-domain observation formulas) for one snapshot."""
    C, E = len(inst.commodities), len(inst.edges)
    q = [z3.Int('q!%d' % c, ctx=ctx) for c in range(C)]
    cons = []
    bounds = inst.snapshots[si].bounds
    for c in range(C):
        cons += [q[c] >= bounds[c][0], q[c] <= bounds[c][1]]
    link = []
    for ei in range(E):
        scale, coeffs = inst.edge_coeff[ei]
        terms = [coeffs[c] * q[c] for c in range(C) if coeffs[c]]
        expr = z3.Sum(terms) if terms else z3.IntVal(0, ctx=ctx)
        link.append(expr)
        if terms:
            cons.append(expr <= scale * inst.edges[ei].capacity)
    domobs = {}
    for obs in inst.snapshots[si].observations:
        if obs.metric == 'demand':
            expr = q[inst.commodity_index[obs.target]]
            lo, hi = obs.lower, obs.upper
        elif obs.metric == 'link':
            ei = inst.edge_index[obs.target]
            scale = inst.edge_coeff[ei][0]
            expr, lo, hi = link[ei], scale * obs.lower, scale * obs.upper
        elif obs.metric == 'ingress':
            idx = inst.ingress_indices[obs.target]
            expr = z3.Sum([q[c] for c in idx]) if idx else z3.IntVal(0, ctx=ctx)
            lo, hi = obs.lower, obs.upper
        else:
            idx = inst.egress_indices[obs.target]
            expr = z3.Sum([q[c] for c in idx]) if idx else z3.IntVal(0, ctx=ctx)
            lo, hi = obs.lower, obs.upper
        sat = z3.And(expr >= lo, expr <= hi)
        if obs.domain is None:
            cons.append(sat)
        else:
            domobs.setdefault(obs.domain, []).append(sat)
    return q, link, cons, domobs


def measure(style, seed):
    x = genbig.gen(seed, style)
    inst = parse_request(json.loads(json.dumps(x)))
    Dobs = inst.observed_domains()
    # ---- per-snapshot feasibility oracle (pure ILP, no booleans)
    oracles = []
    for si in range(len(inst.snapshots)):
        ctx = z3.Context()
        sol = z3.Solver(ctx=ctx)
        q, link, cons, domobs = snapshot_base(inst, si, ctx)
        sol.add(cons)
        oracles.append((sol, domobs, q, link))
    memo = {}

    def feas(si, R):
        key = (si, R)
        if key in memo:
            return memo[key]
        sol, domobs, _, _ = oracles[si]
        sol.push()
        for d in R:
            for s in domobs.get(d, ()):
                sol.add(s)
        r = sol.check() == z3.sat
        sol.pop()
        memo[key] = r
        return r

    # ---- minimal blame sets per snapshot: complements of maximal feasible requirement sets
    def maxsets(cand, must):
        """Maximal feasible S with must ⊆ S ⊆ cand (feas(S), monotone downward)."""
        if feas_all(cand | must):
            return [cand | must]
        if not cand:
            return []
        d = sorted(cand)[0]
        rest = cand - {d}
        out = []
        if feas_all(must | {d}):
            out += maxsets(rest, must | {d})
        if feas_all(must | rest) or True:
            for S in maxsets(rest, must):
                if not (feas_all(S | {d}) and d not in S):
                    out.append(S) if d not in S else None
        # careful: keep only sets not containing d that are maximal w.r.t. d
        res = [S for S in out if d not in S]
        return res

    def feas_all(R):
        return all(feas(si, R) for si in range(len(inst.snapshots)))

    # For the experiment: per-snapshot minimal blame sets (single-snapshot oracle)
    def maxsets1(si, cand, must):
        if feas(si, cand | must):
            return [cand | must]
        if not cand:
            return []
        d = sorted(cand)[0]
        rest = cand - {d}
        out = []
        if feas(si, must | {d}):
            out += maxsets1(si, rest, must | {d})
        for S in maxsets1(si, rest, must):
            if not feas(si, S | {d}):
                out.append(S)
        return out

    t0 = time.process_time()
    allsets = frozenset(Dobs)
    minblame = {}
    for si in range(len(inst.snapshots)):
        if feas(si, allsets):
            minblame[si] = [frozenset()]
        else:
            ms = maxsets1(si, allsets - frozenset(), frozenset())
            minblame[si] = [allsets - M for M in ms]
    t_ms = time.process_time() - t0
    print('%s seed=%d: |Dobs|=%d minblame sizes=%s computed in %.2fs (%d oracle calls)'
          % (style, seed, len(Dobs), {si: sorted(len(v) for v in minblame[si]) for si in minblame}, t_ms, len(memo)))
    return inst, Dobs, minblame, oracles, memo


for style, seed in [('tight', 1), ('wide', 0), ('narrow', 2)]:
    measure(style, seed)
